head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt60102";
scwin.upd_imgFile = null;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — mode

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_85", fn: function(){ return ((dma_pageContext.get("mode") ?? "") === 'insert'); } }, { id: "c_otherwise_87", fn: function(){ return (!(((dma_pageContext.get("mode") ?? "") === 'insert'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_mode", fn: function () { return String(String((dma_pageContext.get("mode") ?? ""))); } },
        { childId: "ipt_key", fn: function () { return String(String((dma_pageContext.get("key") ?? ""))); } },
        { childId: "ipt_description", fn: function () { return String(String((dma_pageContext.get("description") ?? ""))); } },
        { childId: "ipt_width", fn: function () { return String(String((dma_pageContext.get("width") ?? ""))); } },
        { childId: "ipt_height", fn: function () { return String(String((dma_pageContext.get("height") ?? ""))); } },
        { childId: "ipt_from", fn: function () { return String(String((dma_pageContext.get("from") ?? ""))); } },
        { childId: "ipt_to", fn: function () { return String(String((dma_pageContext.get("to") ?? ""))); } },
        { childId: "ipt_imgFileText", fn: function () { return String(String((dma_pageContext.get("name") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    const f = (document.frm || { elements: [] });
    const mode = (String(((dma_pageContext.get("mode") ?? "")) == null ? '' : ((dma_pageContext.get("mode") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("mode") ?? "")) == null ? '' : ((dma_pageContext.get("mode") ?? ""))));
    if (mode === 'modify') {
        $c.util.getComponent('ipt_key').setStyle("background-color", "#EEEEEE");
        $c.util.getComponent('ipt_imgFileText').setStyle("background-color", "#EEEEEE");
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_frm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.upd_imgFile = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_imgFile') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_imgFile"]');
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt60102.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_width_onkeypress
 * @description ipt_width onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_width_onkeypress = function(e){
    try {
        const ev = e;
        const event = ev;
        if ($c.util.getKeyCode(event) < 48 || $c.util.getKeyCode(event) > 57){event.returnValue = false;}

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt60102.ipt_width_onkeypress' }); }
};

/**
 * @method
 * @name ipt_height_onkeypress
 * @description ipt_height onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_height_onkeypress = function(e){
    try {
        const ev = e;
        const event = ev;
        if ($c.util.getKeyCode(event) < 48 || $c.util.getKeyCode(event) > 57){event.returnValue = false;}

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt60102.ipt_height_onkeypress' }); }
};

/**
 * @method
 * @name ipt_from_onkeypress
 * @description ipt_from onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_from_onkeypress = function(e){
    try {
        const ev = e;
        const event = ev;
        if ($c.util.getKeyCode(event) < 48 || $c.util.getKeyCode(event) > 57){event.returnValue = false;}

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt60102.ipt_from_onkeypress' }); }
};

/**
 * @method
 * @name ipt_from_onblur
 * @description ipt_from 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_from_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("ipt_from"))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt60102.ipt_from_onblur' }); }
};

/**
 * @method
 * @name ipt_to_onkeypress
 * @description ipt_to onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_to_onkeypress = function(e){
    try {
        const ev = e;
        const event = ev;
        if ($c.util.getKeyCode(event) < 48 || $c.util.getKeyCode(event) > 57){event.returnValue = false;}

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt60102.ipt_to_onkeypress' }); }
};

/**
 * @method
 * @name ipt_to_onblur
 * @description ipt_to 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_to_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("ipt_to"))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt60102.ipt_to_onblur' }); }
};

/**
 * @method
 * @name img_104_onclick
 * @description img_104 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_104_onclick = async function(e){
    try {
        await scwin.insert()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt60102.img_104_onclick' }); }
};

/**
 * @method
 * @name img_105_onclick
 * @description img_105 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_105_onclick = function(e){
    try {
        scwin.list()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt60102.img_105_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Insert
 * @description Insert 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Insert = async function () {
    const sbmOptions = {
        id: "tx_fn_Insert",
        method: "post",
        action: "/filing/popupManage.do?method=popupInsert",
        ref: "dma_InsertReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name insert
 * @description insert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function () {
    if (($c.util.getComponent('ipt_key').getValue() == null ? '' : String($c.util.getComponent('ipt_key').getValue())) === '') {
        await $c.win.alert("키값을 입력해주세요.");
        $c.util.getComponent("ipt_key").focus();
        return;
    } else {
        if (($c.util.getComponent('ipt_width').getValue() == null ? '' : String($c.util.getComponent('ipt_width').getValue())) === '') {
            await $c.win.alert("넒이값을 입력해주세요.");
            $c.util.getComponent("ipt_width").focus();
            return;
        } else {
            if (($c.util.getComponent('ipt_height').getValue() == null ? '' : String($c.util.getComponent('ipt_height').getValue())) === '') {
                await $c.win.alert("높이값을 입력해주세요.");
                $c.util.getComponent("ipt_height").focus();
                return;
            } else {
                if (($c.util.getComponent('ipt_from').getValue() == null ? '' : String($c.util.getComponent('ipt_from').getValue())) === '') {
                    await $c.win.alert("From을  입력해주세요.");
                    $c.util.getComponent("ipt_from").focus();
                    return;
                } else {
                    if (($c.util.getComponent('ipt_to').getValue() == null ? '' : String($c.util.getComponent('ipt_to').getValue())) === '') {
                        await $c.win.alert("to을  입력해주세요.");
                        $c.util.getComponent("ipt_to").focus();
                        return;
                    }
                }
            }
        }
    }
    if ((String(((dma_pageContext.get("mode") ?? "")) == null ? '' : ((dma_pageContext.get("mode") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("mode") ?? "")) == null ? '' : ((dma_pageContext.get("mode") ?? "")))) === 'insert' && !document.frm.url.checked) {
        if (($c.util.getComponent('upd_imgFile').getValue() == null ? '' : String($c.util.getComponent('upd_imgFile').getValue())) === '') {
            await $c.win.alert("파일을 입력해주세요.");
            return;
        }
    } else {
        if ((String(((dma_pageContext.get("mode") ?? "")) == null ? '' : ((dma_pageContext.get("mode") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("mode") ?? "")) == null ? '' : ((dma_pageContext.get("mode") ?? "")))) === 'insert' && document.frm.url.checked) {
            if (($c.util.getComponent('ipt_imgFileText').getValue() == null ? '' : String($c.util.getComponent('ipt_imgFileText').getValue())) === '') {
                await $c.win.alert("URL 경로를 입력해주세요.");
                return;
            }
        }
    }
    scwin.form_frm.action = "/filing/popupManage.do?method=popupInsert";
    await scwin.tx_fn_Insert();
};

/**
 * @method
 * @name list
 * @description list 처리
 * @returns {void}
 * @hidden N
 */
scwin.list = function () {
    $c.win.moveUrl("/filing/popupManage.do?method=mainAction");
};

/**
 * @method
 * @name checkDate
 * @description check Date 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkDate = async function (obj) {
    if (obj.getValue().length === 0) {
        return true;
    }
    if (obj.getValue().length !== 8) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(obj) + ': ' + '날짜는 8 자리 YYYYMMDD 형식입니다.');
        obj.focus();
        return false;
    }
    const year = obj.getValue().substring(0, 4);
    const month = obj.getValue().substring(4, 6);
    const day = obj.getValue().substring(6, 8);
    if (month > 12 || month < 1) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(obj) + ': ' + '달은 1 에서 12 사이여야 합니다.');
        obj.focus();
        return false;
    }
    if (day > 31 || day < 1) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(obj) + ': ' + '날은 1 에서 31 사이여야 합니다.');
        obj.focus();
        return false;
    }
};

/**
 * @method
 * @name setUrl
 * @description set Url 처리
 * @returns {void}
 * @hidden N
 */
scwin.setUrl = function () {
    const f = (document.frm || { elements: [] });
    if (f.url.checked) {
        $c.util.getComponent('txt_id1').setLabel("URL");
        self.id2.innerHTML = "<input type='text' name='imgFileText' class='form_text' value='http://'}/>";
    } else {
        $c.util.getComponent('txt_id1').setLabel("파일업로드");
        self.id2.innerHTML = "<input type='file' name='imgFile' class='form_text'} value=''/>";
    }
};
